style.css:
/* Global rounding on almost all UI elements */
*, 
div, 
section, 
header, 
nav, 
aside, 
main, 
footer, 
button, 
input, 
textarea, 
article, 
img, 
video, 
figure, 
[role="dialog"], 
[role="menu"], 
[role="button"], 
[role="textbox"] {
    border-radius: 24px !important;
}

/* Extra rounded edges for large containers */
[data-testid="primaryColumn"],
[data-testid="sidebarColumn"],
[data-testid="rightSidebar"],
div[aria-label="Timeline: Your Home Timeline"],
div[aria-label="Primary navigation"] {
    border-radius: 32px !important;
}

/* Round tweet images perfectly */
article img {
    border-radius: 20px !important;
}

/* Round buttons even more */
button {
    border-radius: 9999px !important; /* cute pill shape */
}

/* Round search bar */
input[type="text"],
input[role="combobox"] {
    border-radius: 9999px !important;
}

/* Round cards, pop-ups, dropdowns */
div[role="menu"],
div[role="dialog"],
div[data-testid="sheetDialog"],
div[data-testid="Dropdown"] {
    border-radius: 28px !important;
    overflow: hidden !important; /* ensures clean corners */
}

/* Round tweet cards (if you want them EXTRA soft) */
article {
    border-radius: 28px !important;
}

/* Round profile pictures into softer circles */
img[alt*="Avatar"],
[aria-label="User avatar"] img {
    border-radius: 50% !important;
}
